def default_config():
 return {**{p:{k:d for k,_,_,d in fs} for p,fs in FIELDS.items()},'layout':{p:[{'id':k,'visible':True,'spacing':'original','align':'original','tone':'original'} for k,_ in ss] for p,ss in SECTIONS.items()}}
def merged_config(stored):
 result=default_config()
 for p in FIELDS:result[p].update({k:v for k,v in stored.get(p,{}).items() if k in result[p]})
 # Upgrade the former default label without replacing a customized label.
 if result['general']['nav_login']=='Entrar':result['general']['nav_login']='Dashboard'
 for p in SECTIONS:
  if p in stored.get('layout',{}):result['layout'][p]=deepcopy(stored['layout'][p])
 return result
def field_schema():
 return {p:[{'key':k,'label':l,'type':t,'max':5000 if t=='textarea' else 500} for k,l,t,_ in fs] for p,fs in FIELDS.items()}
